constexpr int fib(int n) {
    return (n <= 1) ? n : (fib(n - 1) + fib(n - 2));
}

// Forces compile-time evaluation
constexpr int CT_RESULT = fib(10);
const int ARRAY_SIZE = fib(5);

// Allowed in array context
int cache[ARRAY_SIZE];

// Runtime evaluation (if 'runtime_input' is not constant)
int runtime_input = 7;
int RT_RESULT = fib(runtime_input);

// Constexpr classes (C++11/14+)
class ConstData {
    int val;
public:
    constexpr ConstData(int v) : val(v) {}
    constexpr int getVal() const { return val; }
};
constexpr ConstData cd(10);
constexpr int v = cd.getVal();
